package com.chatgptcourses.operations.service;

import static com.chatgptcourses.account.service.AccountOperations.*;
import static com.chatgptcourses.operations.service.ContentCaseTypes.*;
import com.chatgptcourses.support.service.SupportTypes.SupportContext;
import com.chatgptcourses.shared.http.ApiError;
import com.chatgptcourses.shared.http.EntityTags;
import com.chatgptcourses.shared.http.RevisionPreconditions;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ContentCaseService {
    private final OperationsStore db;private final com.chatgptcourses.catalog.service.PublicCatalogueService catalogue;
    public ContentCaseService(OperationsStore db,com.chatgptcourses.catalog.service.PublicCatalogueService catalogue){this.db=db;this.catalogue=catalogue;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public ContentCasePage list(UUID actor,Instant from,Instant to,String state,UUID resource,int page,int size){db.auth.require(actor,"content.cases.read");OperationsStore.period(from,to);page(page,size);if(state!=null)check(STATES.contains(state));String where=" WHERE created_at>=? AND created_at<?";var args=new ArrayList<Object>(List.of(Timestamp.from(from),Timestamp.from(to)));if(state!=null){where+=" AND state=?";args.add(state);}if(resource!=null){where+=" AND resource_id=?";args.add(resource);}long total=db.jdbc.queryForObject("SELECT count(*) FROM editorial_cases"+where,Long.class,args.toArray());args.add(size);args.add((long)page*size);var ids=db.jdbc.query("SELECT id FROM editorial_cases"+where+" ORDER BY created_at DESC,id LIMIT ? OFFSET ?",(r,n)->r.getObject(1,UUID.class),args.toArray());return new ContentCasePage(ids.stream().map(id->row(id,false)).toList(),page,size,total);}
    @Transactional(readOnly=true)
    public ContentCaseView get(UUID actor,UUID id){db.auth.require(actor,"content.cases.read");return row(id,false);}
    @Transactional
    public ContentCaseCreation create(UUID actor,UUID context,String idem,CreateContentCase command){db.auth.mutation(actor,context,"content.cases.manage");validate(command);UUID key=key(idem);byte[] hash=db.hash(command);if(command.ticketId()!=null){db.auth.require(actor,"support.admin.read");db.lockTicket(actor,command.ticketId());}else db.lockParticipants(actor,null);db.auth.mutation(actor,context,"content.cases.manage");if(command.ticketId()!=null)db.auth.require(actor,"support.admin.read");var replay=db.replay(actor,"CASE_CREATE",key,hash);if(replay!=null)return new ContentCaseCreation(row(replay.id(),false),false);var result=insert(actor,command);db.remember(actor,"CASE_CREATE",key,hash,"CONTENT_CASE",result.value().id());return result;}
    @Transactional(propagation=Propagation.MANDATORY)
    public void reportFromSupport(UUID actor,UUID ticket,SupportContext context){if(context==null||context.resourceId()==null)return;boolean chosen=Boolean.TRUE.equals(db.jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM support_tickets WHERE id=? AND owner_id=? AND category='CONTENT' AND context_json->>'resourceId'=? AND context_json->>'versionId'=? AND context_json->>'locale'=?)",Boolean.class,ticket,actor,context.resourceId().toString(),context.versionId().toString(),context.locale()));check(chosen);insert(actor,new CreateContentCase(ticket,context.resourceId(),context.versionId(),context.revisionId(),context.locale(),"CONTENT_REPORT"));}
    private ContentCaseCreation insert(UUID actor,CreateContentCase c){db.jdbc.query("SELECT id FROM learning_resources WHERE id=? FOR SHARE",(r,n)->r.getObject(1,UUID.class),c.resourceId());if(c.ticketId()!=null){var old=db.jdbc.query("SELECT id FROM editorial_cases WHERE ticket_id=? AND resource_id=? AND version_id=? AND locale=?",(r,n)->r.getObject(1,UUID.class),c.ticketId(),c.resourceId(),c.versionId(),c.locale());if(!old.isEmpty())return new ContentCaseCreation(row(old.getFirst(),false),false);}
        var sources=db.jdbc.query("SELECT t.id,e.id AS source,e.title FROM content_translations t JOIN pedagogical_versions v ON v.id=t.pedagogical_version_id JOIN editorial_revisions e ON e.id=coalesce(?::uuid,t.published_revision_id,t.current_revision_id) AND e.translation_id=t.id WHERE t.pedagogical_version_id=? AND v.resource_id=? AND t.locale=?",(r,n)->new Source(r.getObject("id",UUID.class),r.getObject("source",UUID.class),r.getString("title")),c.sourceRevisionId(),c.versionId(),c.resourceId(),c.locale());if(sources.isEmpty())throw error(ApiError.RESOURCE_NOT_FOUND);var source=sources.getFirst();UUID id=UUID.randomUUID();var stamp=db.now();db.jdbc.update("INSERT INTO editorial_cases(id,ticket_id,resource_id,version_id,translation_id,source_revision_id,locale,title,state,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,'OPEN',?,?)",id,c.ticketId(),c.resourceId(),c.versionId(),source.translation(),source.revision(),c.locale(),source.title(),stamp,stamp);event(actor,id,"CREATE",c.reason(),null,stamp);db.audit(actor,"CONTENT_CASE_CREATE","CONTENT_CASE",id,"CONTENT_CASE","OPEN");return new ContentCaseCreation(row(id,false),true);}
    @Transactional
    public ContentCaseView update(UUID actor,UUID context,UUID id,String ifMatch,String idem,UpdateContentCase command){db.auth.mutation(actor,context,"content.cases.manage");check(command!=null&&command.state()!=null&&STATES.contains(command.state()));text(command.reason(),2000);UUID key=key(idem);byte[] hash=db.hash(Arrays.asList(id,command));db.lockParticipants(actor,null);var current=row(id,true);db.auth.mutation(actor,context,"content.cases.manage");if(db.replay(actor,"CASE_UPDATE",key,hash)!=null)return current;RevisionPreconditions.requireMatch(ifMatch,tag(current));db.assignee(command.assigneeId(),"content.cases.manage");if("RESOLVED".equals(command.state())){check(command.correctedRevisionId()!=null);if(command.correctedRevisionId().equals(current.sourceRevisionId()))throw error(ApiError.CONTENT_CASE_CONFLICT);db.jdbc.query("SELECT id FROM learning_resources WHERE id=? FOR SHARE",(r,n)->r.getObject(1,UUID.class),current.resourceId());var versions=db.jdbc.query("SELECT t.pedagogical_version_id FROM editorial_revisions e JOIN content_translations t ON t.id=e.translation_id JOIN pedagogical_versions v ON v.id=t.pedagogical_version_id WHERE e.id=? AND v.resource_id=? AND t.locale=?",(r,n)->r.getObject(1,UUID.class),command.correctedRevisionId(),current.resourceId(),current.locale());if(versions.isEmpty())throw error(ApiError.CONTENT_CASE_CONFLICT);var published=catalogue.version(current.resourceId(),versions.getFirst(),current.locale());if(!"PUBLISHED".equals(published.availability())||!command.correctedRevisionId().equals(published.revisionId()))throw error(ApiError.CONTENT_CASE_CONFLICT);}else check(command.correctedRevisionId()==null);var stamp=db.jdbc.queryForObject("SELECT greatest(clock_timestamp(),updated_at+interval '1 microsecond',coalesce((SELECT max(created_at)+interval '1 microsecond' FROM editorial_case_events WHERE case_id=?),created_at)) FROM editorial_cases WHERE id=?",Timestamp.class,id,id);db.jdbc.update("UPDATE editorial_cases SET state=?,assignee_id=?,corrected_revision_id=?,revision=revision+1,updated_at=? WHERE id=?",command.state(),command.assigneeId(),command.correctedRevisionId(),stamp,id);event(actor,id,"UPDATE",command.reason(),command.correctedRevisionId(),stamp);db.remember(actor,"CASE_UPDATE",key,hash,"CONTENT_CASE",id);db.audit(actor,"CONTENT_CASE_UPDATE","CONTENT_CASE",id,"CONTENT_CASE",command.state());return row(id,false);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public ContentCaseEventPage events(UUID actor,UUID id,int page,int size){db.auth.require(actor,"content.cases.read");row(id,false);page(page,size);long total=db.jdbc.queryForObject("SELECT count(*) FROM editorial_case_events WHERE case_id=?",Long.class,id);var items=db.jdbc.query("SELECT * FROM editorial_case_events WHERE case_id=? ORDER BY entry_number LIMIT ? OFFSET ?",(r,n)->new ContentCaseEvent(r.getObject("id",UUID.class),id,r.getObject("actor_id",UUID.class),r.getString("action"),r.getString("reason"),r.getObject("corrected_revision_id",UUID.class),instant(r,"created_at")),id,size,(long)page*size);return new ContentCaseEventPage(items,page,size,total);}
    private ContentCaseView row(UUID id,boolean lock){var rows=db.jdbc.query("SELECT * FROM editorial_cases WHERE id=?"+(lock?" FOR UPDATE":""),(r,n)->new ContentCaseView(id,r.getLong("revision"),r.getObject("ticket_id",UUID.class),r.getObject("resource_id",UUID.class),r.getObject("version_id",UUID.class),r.getObject("source_revision_id",UUID.class),r.getObject("translation_id",UUID.class),r.getString("locale"),r.getString("title"),r.getString("state"),r.getObject("assignee_id",UUID.class),r.getObject("corrected_revision_id",UUID.class),instant(r,"created_at"),instant(r,"updated_at")),id);if(rows.isEmpty())throw error(ApiError.RESOURCE_NOT_FOUND);return rows.getFirst();}
    private void event(UUID actor,UUID id,String action,String reason,UUID corrected,Timestamp stamp){db.jdbc.update("INSERT INTO editorial_case_events(id,case_id,actor_id,action,reason,corrected_revision_id,entry_number,created_at) SELECT ?,?,?,?,?,?,coalesce(max(entry_number),0)+1,? FROM editorial_case_events WHERE case_id=?",UUID.randomUUID(),id,actor,action,reason,corrected,stamp,id);}
    private static void validate(CreateContentCase c){check(c!=null&&c.resourceId()!=null&&c.versionId()!=null);locale(c.locale());text(c.reason(),2000);}
    public static String tag(ContentCaseView value){return EntityTags.forRevision("content-case",value.id(),value.revision());}
    private static final Set<String> STATES=Set.of("OPEN","IN_PROGRESS","RESOLVED","DISMISSED");
    private record Source(UUID translation,UUID revision,String title) { }
}
